settings._custom_css:
selector { position: relative; display: block; }
        selector::after {
            content: '▶';
            position: absolute;
            top: 50%; left: 50%;
            transform: translate(-50%, -50%);
            color: white;
            font-size: 48px;
            pointer-events: none;
            text-shadow: 0 4px 12px rgba(0,0,0,0.5);
            opacity: 0.9;
        }
        selector:hover::after { opacity: 1; transform: translate(-50%, -50%) scale(1.1); transition: 0.3s; }

